package com.college.grievance.controller;
import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import com.college.grievance.dao.ComplaintDAO;import com.college.grievance.model.User;import java.io.*;
@WebServlet("/admin") public class AdminServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{try{User u=(User)q.getSession().getAttribute("user");if(u==null||!"ADMIN".equals(u.role)){r.sendError(403);return;}ComplaintDAO d=new ComplaintDAO();q.setAttribute("complaints",d.all(q.getParameter("search"),q.getParameter("status")));q.setAttribute("total",d.count(null));q.setAttribute("pending",d.count("Pending"));q.setAttribute("progress",d.count("In Progress"));q.setAttribute("resolved",d.count("Resolved"));q.getRequestDispatcher("admin.jsp").forward(q,r);}catch(Exception e){throw new ServletException(e);}}}